parameters.jsCode:
const execution = $json.execution;
const workflow = $json.workflow;
const lastNode = execution.lastNodeExecuted;
const errorData = execution.error;

return [{
  json: {
    workflowId: workflow.name || 'sutra_pipeline',
    workflowIdKey: workflow.id,
    executionId: execution.id,
    failedNode: lastNode,
    errorMessage: errorData.message || 'Unknown pipeline execution failure',
    errorStack: errorData.stack || '',
    timestamp: new Date().toISOString(),
    orderId: execution.data?.resultData?.runData?.[lastNode]?.[0]?.data?.main?.[0]?.[0]?.json?.orderId || 
             execution.data?.resultData?.runData?.['Intake Webhook (Verified Payment)']?.[0]?.data?.main?.[0]?.[0]?.json?.body?.orderId || null,
  }
}];

